# Note-format benchmark for GLAMARC-style routing
# Fix: note content is now built per-sample, so every note field is a scalar.
# Tests:
#   - JSON
#   - Table
#   - Q&A
#   - Compact text
# against a structured chooser and a rule mix baseline.
#
# Datasets:
#   - Breast Cancer
#   - FashionMNIST
#   - 20 Newsgroups
#
# CPU-only, text-only output.

