import math
import random
import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score

# -----------------------------
# Reproducibility
# -----------------------------
SEED = 42
def set_seed(seed=SEED):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

set_seed(SEED)
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
GATE_NAMES = ["Compute", "Route", "Memory", "Control"]


# -----------------------------
# Persistent memory
# -----------------------------
class MemoryBuffer(nn.Module):
    def __init__(self, dim: int, max_slots: int = 512, topk: int = 8):
        super().__init__()
        self.dim = dim
        self.max_slots = max_slots
        self.topk = topk
        self.register_buffer("keys", torch.empty(0, dim))
        self.register_buffer("values", torch.empty(0, dim))

    @torch.no_grad()
    def update(self, keys: torch.Tensor, values: torch.Tensor):
        """
        keys:   [B, D]
        values: [B, D]
        """
        if keys.numel() == 0:
            return

        k = F.normalize(keys.detach(), dim=-1)
        v = values.detach()

        if self.keys.numel() == 0:
            self.keys = k[-self.max_slots:].clone()
            self.values = v[-self.max_slots:].clone()
            return

        self.keys = torch.cat([self.keys, k], dim=0)[-self.max_slots:]
        self.values = torch.cat([self.values, v], dim=0)[-self.max_slots:]

    def read(self, query: torch.Tensor) -> torch.Tensor:
        """
        query: [B, D]
        returns: [B, D]
        """
        if self.keys.numel() == 0:
            return torch.zeros_like(query)

        q = F.normalize(query, dim=-1)
        scores = torch.matmul(q, self.keys.T) / math.sqrt(self.dim)  # [B, M]
        k = min(self.topk, scores.shape[1])

        top_scores, top_idx = torch.topk(scores, k=k, dim=1)
        top_vals = self.values[top_idx]  # [B, k, D]
        weights = F.softmax(top_scores, dim=1)
        ctx = (weights.unsqueeze(-1) * top_vals).sum(dim=1)
        return ctx


# -----------------------------
# Experts
# -----------------------------
class ComputeExpert(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(dim, dim),
            nn.GELU(),
            nn.Linear(dim, dim),
        )

    def forward(self, h: torch.Tensor, memory: MemoryBuffer | None = None):
        return self.net(h)


class RouteExpert(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.fuse = nn.Sequential(
            nn.Linear(dim * 2, dim),
            nn.GELU(),
            nn.Linear(dim, dim),
        )

    def forward(self, h: torch.Tensor, memory: MemoryBuffer | None = None):
        ctx = memory.read(h) if memory is not None else torch.zeros_like(h)
        return self.fuse(torch.cat([h, ctx], dim=-1))


class MemoryExpert(nn.Module):
    def __init__(self, dim: int, memory: MemoryBuffer):
        super().__init__()
        self.memory = memory
        self.fuse = nn.Sequential(
            nn.Linear(dim * 2, dim),
            nn.GELU(),
            nn.Linear(dim, dim),
        )

    def forward(self, h: torch.Tensor, memory: MemoryBuffer | None = None):
        mem = self.memory.read(h)
        return self.fuse(torch.cat([h, mem], dim=-1))


class ControlExpert(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(dim, dim),
            nn.Tanh(),
            nn.Linear(dim, dim),
        )

    def forward(self, h: torch.Tensor, memory: MemoryBuffer | None = None):
        return self.net(h)


# -----------------------------
# MasterFabric
# -----------------------------
class MasterFabric(nn.Module):
    def __init__(self, input_dim: int, hidden_dim: int, num_classes: int = 10):
        super().__init__()
        self.input_proj = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.LayerNorm(hidden_dim),
            nn.GELU(),
            nn.Linear(hidden_dim, hidden_dim),
        )

        self.audit_in = nn.Linear(hidden_dim, hidden_dim)
        self.audit_out = nn.Linear(hidden_dim, hidden_dim)

        self.router = nn.Linear(hidden_dim * 2, 4)
        self.flashlight = nn.Sequential(
            nn.Linear(hidden_dim, hidden_dim // 2),
            nn.GELU(),
            nn.Linear(hidden_dim // 2, 1),
        )

        self.memory = MemoryBuffer(hidden_dim, max_slots=512, topk=8)

        self.experts = nn.ModuleDict({
            "Compute": ComputeExpert(hidden_dim),
            "Route": RouteExpert(hidden_dim),
            "Memory": MemoryExpert(hidden_dim, self.memory),
            "Control": ControlExpert(hidden_dim),
        })

        self.classifier = nn.Linear(hidden_dim, num_classes)

    def expert_outputs(self, x: torch.Tensor):
        h = self.input_proj(x)
        outs = []
        outs.append(self.experts["Compute"](h, self.memory))
        outs.append(self.experts["Route"](h, self.memory))
        outs.append(self.experts["Memory"](h, self.memory))
        outs.append(self.experts["Control"](h, self.memory))
        return h, torch.stack(outs, dim=1)  # [B, 4, H]

    def forward(self, x: torch.Tensor, temperature: float = 1.0, update_memory: bool = True):
        h, all_outs = self.expert_outputs(x)

        entry_note = self.audit_in(h)
        router_logits = self.router(torch.cat([h, entry_note], dim=-1))

        if self.training:
            gate_onehot = F.gumbel_softmax(router_logits, tau=temperature, hard=True)
        else:
            gate_idx = torch.argmax(router_logits, dim=-1)
            gate_onehot = F.one_hot(gate_idx, num_classes=4).float()

        out = (all_outs * gate_onehot.unsqueeze(-1)).sum(dim=1)

        burst_prob = torch.sigmoid(self.flashlight(h)).squeeze(-1)
        out = out * (1.0 + 0.08 * burst_prob.unsqueeze(-1))

        exit_note = self.audit_out(out)
        audit_loss = F.mse_loss(entry_note, exit_note)

        logits = self.classifier(out)

        if update_memory:
            with torch.no_grad():
                self.memory.update(h, out)

        return {
            "logits": logits,
            "router_logits": router_logits,
            "gate_onehot": gate_onehot,
            "gate_idx": gate_onehot.argmax(dim=-1),
            "audit_loss": audit_loss,
            "burst_prob": burst_prob,
            "latent": out,
            "hidden": h,
        }


# -----------------------------
# Training + evaluation
# -----------------------------
def train_fabric(model, X_train, y_train, epochs=20, batch_size=64, lr=1e-3,
                 audit_w=0.20, gate_w=0.50, entropy_w=0.01, temperature=1.0):
    model.train()
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    n = X_train.shape[0]

    for epoch in range(1, epochs + 1):
        perm = torch.randperm(n, device=X_train.device)
        total_loss = 0.0
        total_task = 0.0
        total_gate = 0.0
        total_audit = 0.0

        for start in range(0, n, batch_size):
            idx = perm[start:start + batch_size]
            xb = X_train[idx]
            yb = y_train[idx]

            with torch.no_grad():
                # Oracle gate for training: best expert under current experts + shared classifier.
                h_tmp, outs_tmp = model.expert_outputs(xb)
                expert_logits_tmp = model.classifier(outs_tmp.reshape(-1, outs_tmp.shape[-1])).view(xb.shape[0], 4, -1)
                probs_tmp = F.softmax(expert_logits_tmp, dim=-1)
                true_prob = probs_tmp[torch.arange(xb.shape[0], device=xb.device), :, yb]
                oracle_gate = torch.argmax(true_prob, dim=1)

            out = model(xb, temperature=temperature, update_memory=True)
            logits = out["logits"]
            router_logits = out["router_logits"]
            audit_loss = out["audit_loss"]

            task_loss = F.cross_entropy(logits, yb)
            gate_loss = F.cross_entropy(router_logits, oracle_gate)
            router_probs = F.softmax(router_logits, dim=-1)
            router_entropy = -(router_probs * torch.log(router_probs + 1e-12)).sum(dim=-1).mean()

            loss = task_loss + gate_w * gate_loss + audit_w * audit_loss - entropy_w * router_entropy

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
            opt.step()

            total_loss += loss.item() * xb.shape[0]
            total_task += task_loss.item() * xb.shape[0]
            total_gate += gate_loss.item() * xb.shape[0]
            total_audit += audit_loss.item() * xb.shape[0]

        if epoch == 1 or epoch % 5 == 0 or epoch == epochs:
            print(
                f"Epoch {epoch:02d} | "
                f"loss={total_loss/n:.4f} | "
                f"task={total_task/n:.4f} | "
                f"gate={total_gate/n:.4f} | "
                f"audit={total_audit/n:.4f}"
            )

    return model


@torch.no_grad()
def evaluate_fabric(model, X, y):
    model.eval()
    out = model(X, update_memory=False)
    logits = out["logits"]
    router_logits = out["router_logits"]
    gate_pred = router_logits.argmax(dim=-1)

    h, all_outs = model.expert_outputs(X)
    expert_logits = model.classifier(all_outs.reshape(-1, all_outs.shape[-1])).view(X.shape[0], 4, -1)
    probs = F.softmax(expert_logits, dim=-1)
    true_prob = probs[torch.arange(X.shape[0], device=X.device), :, y]

    oracle_gate = true_prob.argmax(dim=1)
    chosen_logits = expert_logits[torch.arange(X.shape[0], device=X.device), gate_pred]
    oracle_logits = expert_logits[torch.arange(X.shape[0], device=X.device), oracle_gate]

    pred = logits.argmax(dim=-1)
    chosen_pred = chosen_logits.argmax(dim=-1)
    oracle_pred = oracle_logits.argmax(dim=-1)

    task_acc = (chosen_pred == y).float().mean().item()
    model_acc = (pred == y).float().mean().item()
    oracle_task_acc = (oracle_pred == y).float().mean().item()
    gate_acc = (gate_pred == oracle_gate).float().mean().item()
    regret = (true_prob.max(dim=1).values - true_prob[torch.arange(X.shape[0], device=X.device), gate_pred]).mean().item()
    mean_entropy = (-(F.softmax(router_logits, dim=-1) * F.log_softmax(router_logits, dim=-1)).sum(dim=-1)).mean().item()

    return {
        "model_acc": model_acc,
        "task_acc": task_acc,
        "oracle_task_acc": oracle_task_acc,
        "gate_acc": gate_acc,
        "regret": regret,
        "router_entropy": mean_entropy,
        "gate_pred": gate_pred.cpu().numpy(),
        "oracle_gate": oracle_gate.cpu().numpy(),
    }


# -----------------------------
# Smoke test on digits
# -----------------------------
if __name__ == "__main__":
    digits = load_digits()
    X = digits.data.astype(np.float32) / 16.0
    y = digits.target.astype(np.int64)

    X_train, X_test, y_train, y_test = train_test_split(
        X, y, test_size=0.2, random_state=SEED, stratify=y
    )

    X_train = torch.tensor(X_train, dtype=torch.float32, device=device)
    y_train = torch.tensor(y_train, dtype=torch.long, device=device)
    X_test = torch.tensor(X_test, dtype=torch.float32, device=device)
    y_test = torch.tensor(y_test, dtype=torch.long, device=device)

    model = MasterFabric(input_dim=X_train.shape[1], hidden_dim=128, num_classes=10).to(device)
    model = train_fabric(model, X_train, y_train, epochs=15, batch_size=64)

    metrics = evaluate_fabric(model, X_test, y_test)
    print("\nTest metrics:")
    for k, v in metrics.items():
        if not isinstance(v, np.ndarray):
            print(f"  {k}: {v:.4f}")

