def load_breast_cancer_benchmark(seed=42):
    data = load_breast_cancer()
    X = data.data.astype(np.float32)
    y = data.target.astype(np.int64)
    X_train_full, X_test_full, y_train_full, y_test_full = train_test_split(
        X, y, test_size=0.20, random_state=seed, stratify=y
    )
    return X_train_full, y_train_full, X_test_full, y_test_full

def load_fashion_mnist_benchmark(seed=42):
    trainset = tv_datasets.FashionMNIST(root="/content/data", train=True, download=True)
    testset = tv_datasets.FashionMNIST(root="/content/data", train=False, download=True)

    X_train_full = trainset.data.numpy().astype(np.float32) / 255.0
    y_train_full = trainset.targets.numpy().astype(np.int64)
    X_test_full = testset.data.numpy().astype(np.float32) / 255.0
    y_test_full = testset.targets.numpy().astype(np.int64)

    X_train_full = X_train_full.reshape(len(X_train_full), -1)
    X_test_full = X_test_full.reshape(len(X_test_full), -1)
    return X_train_full, y_train_full, X_test_full, y_test_full

def load_20newsgroups_benchmark(seed=42):
    ds_train = fetch_20newsgroups(subset="train", remove=("headers", "footers", "quotes"))
    ds_test = fetch_20newsgroups(subset="test", remove=("headers", "footers", "quotes"))

    X_train_full = np.asarray(ds_train.data, dtype=object)
    y_train_full = np.asarray(ds_train.target, dtype=np.int64)
    X_test_full = np.asarray(ds_test.data, dtype=object)
    y_test_full = np.asarray(ds_test.target, dtype=np.int64)
    return X_train_full, y_train_full, X_test_full, y_test_full

# -----------------------------
# Experts
# -----------------------------
def build_tabular_experts(seed):
    return [
        Pipeline([("scaler", StandardScaler()), ("lr", LogisticRegression(max_iter=500, solver="liblinear", random_state=seed))]),
        Pipeline([("scaler", StandardScaler()), ("knn", KNeighborsClassifier(n_neighbors=5))]),
        DecisionTreeClassifier(max_depth=6, random_state=seed),
        GaussianNB(),
    ]

def predict_tabular_experts(experts, X_eval):
    probs = [m.predict_proba(X_eval) for m in experts]
    preds = np.stack([np.argmax(p, axis=1) for p in probs], axis=1)
    top1_prob = np.stack([np.max(p, axis=1) for p in probs], axis=1)
    p_sorted = [np.sort(p, axis=1) for p in probs]
    margin = np.stack([ps[:, -1] - ps[:, -2] for ps in p_sorted], axis=1)
    entropy = np.stack([(-np.sum(p * np.log(p + 1e-12), axis=1)) / np.log(p.shape[1]) for p in probs], axis=1)
    return preds, probs, top1_prob, margin, entropy

def build_image_experts(seed):
    return [
        Pipeline([("scaler", StandardScaler()), ("lr", LogisticRegression(max_iter=250, solver="lbfgs", random_state=seed))]),
        Pipeline([("scaler", StandardScaler()), ("knn", KNeighborsClassifier(n_neighbors=3, algorithm="brute", n_jobs=-1))]),
        DecisionTreeClassifier(max_depth=25, random_state=seed),
        GaussianNB(),
    ]

def predict_image_experts(experts, X_eval):
    probs = [m.predict_proba(X_eval) for m in experts]
    preds = np.stack([np.argmax(p, axis=1) for p in probs], axis=1)
    top1_prob = np.stack([np.max(p, axis=1) for p in probs], axis=1)
    p_sorted = [np.sort(p, axis=1) for p in probs]
    margin = np.stack([ps[:, -1] - ps[:, -2] for ps in p_sorted], axis=1)
    entropy = np.stack([(-np.sum(p * np.log(p + 1e-12), axis=1)) / np.log(p.shape[1]) for p in probs], axis=1)
    return preds, probs, top1_prob, margin, entropy

def build_text_experts(seed):
    return [
        Pipeline([("tfidf", TfidfVectorizer(max_features=6000, ngram_range=(1, 1), min_df=2)),
                  ("lr", LogisticRegression(max_iter=400, solver="liblinear", random_state=seed))]),
        Pipeline([("tfidf", TfidfVectorizer(max_features=8000, ngram_range=(1, 2), min_df=2)),
                  ("sgd", SGDClassifier(loss="log_loss", max_iter=800, tol=1e-3, random_state=seed))]),
        Pipeline([("tfidf", TfidfVectorizer(max_features=8000, ngram_range=(1, 1), min_df=2)),
                  ("nb", ComplementNB(alpha=0.3))]),
        Pipeline([("tfidf", TfidfVectorizer(analyzer="char", ngram_range=(3, 5), max_features=6000, min_df=2)),
                  ("lr", LogisticRegression(max_iter=400, solver="liblinear", random_state=seed))]),
    ]

def predict_text_experts(experts, X_eval):
    probs = [m.predict_proba(X_eval) for m in experts]
    preds = np.stack([np.argmax(p, axis=1) for p in probs], axis=1)
    top1_prob = np.stack([np.max(p, axis=1) for p in probs], axis=1)
    p_sorted = [np.sort(p, axis=1) for p in probs]
    margin = np.stack([ps[:, -1] - ps[:, -2] for ps in p_sorted], axis=1)
    entropy = np.stack([(-np.sum(p * np.log(p + 1e-12), axis=1)) / np.log(p.shape[1]) for p in probs], axis=1)
    return preds, probs, top1_prob, margin, entropy

# -----------------------------
# Note generation
# -----------------------------
def sample_pair_agreement(gate_preds_i):
    cnt = 0
    agree = 0
    for a in range(4):
        for b in range(a + 1, 4):
            agree += int(gate_preds_i[a] == gate_preds_i[b])
            cnt += 1
    return agree / max(cnt, 1)

def sample_content(dataset_name, modality, i, gate_preds, top1_prob, margin, entropy):
    pair_agree = sample_pair_agreement(gate_preds[i])
    cand = []
    for g in range(4):
        cand.append({
            "gate": GATE_NAMES[g],
            "pred": int(gate_preds[i, g]),
            "top1": float(top1_prob[i, g]),
            "margin": float(margin[i, g]),
            "entropy": float(entropy[i, g]),
            "proxy": float(top1_prob[i, g] - GATE_COST[g]),
        })
    cand = sorted(cand, key=lambda d: d["proxy"], reverse=True)
    return {
        "dataset": dataset_name,
        "modality": modality,
        "signals": {
            "pair_agree": float(pair_agree),
            "top1_mean": float(np.mean(top1_prob[i])),
            "margin_mean": float(np.mean(margin[i])),
            "entropy_mean": float(np.mean(entropy[i])),
        },
        "candidates": cand,
        "best_hint": cand[0]["gate"],
    }

def render_note(content, fmt):
    if fmt == "json":
        return json.dumps(content, sort_keys=True, separators=(",", ":"))

    if fmt == "table":
        lines = []
        lines.append(f"DATASET | {content['dataset']}")
        lines.append(f"MODALITY | {content['modality']}")
        lines.append("")
        lines.append("| Signal | Value |")
        lines.append("|---|---:|")
        for k, v in content["signals"].items():
            lines.append(f"| {k} | {fmt3(v)} |")
        lines.append("")
        lines.append("| Gate | Pred | Top1 | Margin | Entropy | Proxy |")
        lines.append("|---|---:|---:|---:|---:|---:|")
        for c in content["candidates"]:
            lines.append(f"| {c['gate']} | {c['pred']} | {fmt3(c['top1'])} | {fmt3(c['margin'])} | {fmt3(c['entropy'])} | {fmt3(c['proxy'])} |")
        lines.append(f"Best hint | {content['best_hint']}")
        return "\n".join(lines)

    if fmt == "qa":
        lines = []
        lines.append(f"Q1: What kind of data is this?\nA1: {content['modality']} in {content['dataset']}.")
        s = content["signals"]
        lines.append(
            "Q2: What are the main signals?\nA2: "
            f"pair_agree={fmt3(s['pair_agree'])}, top1_mean={fmt3(s['top1_mean'])}, "
            f"margin_mean={fmt3(s['margin_mean'])}, entropy_mean={fmt3(s['entropy_mean'])}."
        )
        cand = "; ".join([f"{c['gate']} proxy={fmt3(c['proxy'])}" for c in content["candidates"]])
        lines.append("Q3: Which gates look strongest?\nA3: " + cand + ".")
        lines.append(f"Q4: Best hint?\nA4: {content['best_hint']}.")
        return "\n".join(lines)

    s = content["signals"]
    cand = " | ".join([f"{c['gate']}({fmt3(c['proxy'])})" for c in content["candidates"]])
    return (
        f"dataset={content['dataset']};modality={content['modality']};"
        f"pair_agree={fmt3(s['pair_agree'])};top1={fmt3(s['top1_mean'])};margin={fmt3(s['margin_mean'])};entropy={fmt3(s['entropy_mean'])};"
        f"cands={cand};best_hint={content['best_hint']}"
    )

def build_note_texts(dataset_name, modality, gate_preds, top1_prob, margin, entropy, fmt):
    texts = []
    for i in range(gate_preds.shape[0]):
        content = sample_content(dataset_name, modality, i, gate_preds, top1_prob, margin, entropy)
        texts.append(render_note(content, fmt))
    return texts

# -----------------------------
# Gain / labels
# -----------------------------
def compute_gate_labels(gate_probs, y_true):
    true_prob = np.stack([gate_probs[g][np.arange(len(y_true)), y_true] for g in range(4)], axis=1)
    gain = true_prob - GATE_COST[None, :]
    best_gate = np.argmax(gain, axis=1)
    return true_prob, gain, best_gate

def evaluate_experts(gate_preds, y_true, best_gate):
    single_accs = [accuracy_score(y_true, gate_preds[:, g]) for g in range(4)]
    best_single_idx = int(np.argmax(single_accs))
    best_single_acc = float(single_accs[best_single_idx])
    oracle_task_acc = float(np.mean([gate_preds[i, best_gate[i]] == y_true[i] for i in range(len(y_true))]))
    pairwise_mean = float(np.mean([np.mean(gate_preds[:, a] == gate_preds[:, b]) for a in range(4) for b in range(a + 1, 4)]))
    return best_single_idx, best_single_acc, oracle_task_acc, pairwise_mean

# -----------------------------
# Data feature builders
# -----------------------------
def build_data_block(dataset_name, X_train_raw, X_test_raw, seed):
    if dataset_name == "Breast Cancer":
        scaler = StandardScaler()
        Xtr = scaler.fit_transform(np.asarray(X_train_raw, dtype=np.float32)).astype(np.float32)
        Xte = scaler.transform(np.asarray(X_test_raw, dtype=np.float32)).astype(np.float32)
        return Xtr, Xte, "dense"

    if dataset_name == "FashionMNIST":
        pipe = Pipeline([
            ("scaler", StandardScaler()),
            ("pca", PCA(n_components=50, random_state=seed)),
        ])
        Xtr = pipe.fit_transform(np.asarray(X_train_raw, dtype=np.float32)).astype(np.float32)
        Xte = pipe.transform(np.asarray(X_test_raw, dtype=np.float32)).astype(np.float32)
        return Xtr, Xte, "dense"

    vec = TfidfVectorizer(max_features=12000, ngram_range=(1, 2), min_df=2)
    Xtr = vec.fit_transform(np.asarray(X_train_raw, dtype=object))
    Xte = vec.transform(np.asarray(X_test_raw, dtype=object))
    return Xtr, Xte, "sparse"

def to_sparse_block(X):
    if issparse(X):
        return X.tocsr()
    return csr_matrix(np.asarray(X, dtype=np.float32))

# -----------------------------
# Meta features from gate outputs
# -----------------------------
def build_meta_block(gate_preds, top1_prob, margin, entropy):
    pair_agree_vals = []
    for a in range(4):
        for b in range(a + 1, 4):
            pair_agree_vals.append((gate_preds[:, a] == gate_preds[:, b]).astype(np.float32))
    pair_agree_vals = np.stack(pair_agree_vals, axis=1)
    pair_agree_mean = pair_agree_vals.mean(axis=1, keepdims=True)
    pair_agree_std = pair_agree_vals.std(axis=1, keepdims=True)
    disagreement = 1.0 - pair_agree_mean

    mem_top1 = top1_prob[:, 2:3]
    mem_margin = margin[:, 2:3]
    mem_entropy = entropy[:, 2:3]
    other_top1_mean = np.delete(top1_prob, 2, axis=1).mean(axis=1, keepdims=True)
    mem_advantage = mem_top1 - other_top1_mean

    top1_mean = top1_prob.mean(axis=1, keepdims=True)
    top1_std = top1_prob.std(axis=1, keepdims=True)
    margin_mean = margin.mean(axis=1, keepdims=True)
    margin_std = margin.std(axis=1, keepdims=True)
    entropy_mean = entropy.mean(axis=1, keepdims=True)
    entropy_std = entropy.std(axis=1, keepdims=True)

    meta = np.concatenate([
        top1_mean, top1_std,
        margin_mean, margin_std,
        entropy_mean, entropy_std,
        pair_agree_mean, pair_agree_std, disagreement,
        mem_top1, mem_margin, mem_entropy, mem_advantage,
    ], axis=1).astype(np.float32)
    return meta

# -----------------------------
# Families
# -----------------------------
def build_family_inputs(family, note_train, note_test, meta_train, meta_test, data_train, data_test):
    if family == "note_only":
        return note_train, note_test
    if family == "meta_only":
        return meta_train, meta_test
    if family == "data_only":
        return data_train, data_test
    if family == "note_plus_meta":
        return sparse_hstack([note_train, meta_train]), sparse_hstack([note_test, meta_test])
    if family == "note_plus_data":
        return sparse_hstack([note_train, data_train]), sparse_hstack([note_test, data_test])
    if family == "meta_plus_data":
        return sparse_hstack([meta_train, data_train]), sparse_hstack([meta_test, data_test])
    if family == "all_signals":
        return sparse_hstack([note_train, meta_train, data_train]), sparse_hstack([note_test, meta_test, data_test])
    raise ValueError(f"Unknown family: {family}")

# -----------------------------
# Deep dive
# -----------------------------
def quartile_report(values, score, name):
    q = np.quantile(values, [0.25, 0.50, 0.75])
    bins = [
        ("Q1_low", values <= q[0]),
        ("Q2_midlow", (values > q[0]) & (values <= q[1])),
        ("Q3_midhigh", (values > q[1]) & (values <= q[2])),
        ("Q4_high", values > q[2]),
    ]
    lines = [f"  {name}:"]
    for label, mask in bins:
        if mask.sum() == 0:
            continue
        lines.append(f"    {label:9s} {score[mask].mean():+.4f}  n={int(mask.sum())}")
    return "\n".join(lines)

# -----------------------------
# Main runner
# -----------------------------
def run_dataset(dataset_name, loader_fn, build_experts_fn, predict_experts_fn, train_fracs, test_n, seeds):
    X_train_full, y_train_full, X_test_full, y_test_full = loader_fn(BASE_SEED)
    if test_n is not None:
        X_test, y_test = stratified_subsample(X_test_full, y_test_full, test_n, BASE_SEED)
    else:
        X_test, y_test = X_test_full, y_test_full

    modality = "tabular" if dataset_name == "Breast Cancer" else ("image" if dataset_name == "FashionMNIST" else "text")

    print(f"\n\n==================== {dataset_name} ====================")
    print("Running router / oracle / signal-source stress test...")

    all_rows = []

    for train_frac in train_fracs:
        train_n = max(int((X_train_full.shape[0] if hasattr(X_train_full, "shape") else len(X_train_full)) * train_frac), 2)

        for seed in seeds:
            set_seed(seed)

            X_sub, y_sub = stratified_subsample(X_train_full, y_train_full, train_n, seed)
            X_expert_train, X_gate_train, y_expert_train, y_gate_train = train_test_split(
                X_sub, y_sub, test_size=0.20, random_state=seed, stratify=y_sub
            )

            experts = build_experts_fn(seed)
            for m in experts:
                m.fit(X_expert_train, y_expert_train)

            gate_preds_tr, gate_probs_tr, top1_tr, margin_tr, entropy_tr = predict_experts_fn(experts, X_gate_train)
            gate_preds_te, gate_probs_te, top1_te, margin_te, entropy_te = predict_experts_fn(experts, X_test)

            _, gain_tr, best_gate_tr = compute_gate_labels(gate_probs_tr, y_gate_train)
            _, gain_te, best_gate_te = compute_gate_labels(gate_probs_te, y_test)

            best_single_idx, best_single_acc, oracle_task_acc, pairwise_mean = evaluate_experts(gate_preds_te, y_test, best_gate_te)
            memory_oracle_rate = float(np.mean(best_gate_te == 2))

            # Note formats
            note_results = {}
            for fmt in NOTE_FORMATS:
                train_notes = build_note_texts(dataset_name, modality, gate_preds_tr, top1_tr, margin_tr, entropy_tr, fmt)
                test_notes = build_note_texts(dataset_name, modality, gate_preds_te, top1_te, margin_te, entropy_te, fmt)

                note_vec = TfidfVectorizer(analyzer="char", ngram_range=(3, 5), min_df=2, max_features=60000)
                X_note_tr = note_vec.fit_transform(train_notes)
                X_note_te = note_vec.transform(test_notes)

                clf = fit_router(X_note_tr, best_gate_tr, seed)
                tr_eval = evaluate_router(clf, X_note_tr, gate_preds_tr, gain_tr, y_gate_train)
                te_eval = evaluate_router(clf, X_note_te, gate_preds_te, gain_te, y_test)

                note_results[fmt] = {
                    "train_eval": tr_eval,
                    "test_eval": te_eval,
                    "train_notes": train_notes,
                    "test_notes": test_notes,
                    "vec": note_vec,
                }

            ranked_notes = sorted(
                [(fmt, note_results[fmt]["test_eval"]["gate_acc"]) for fmt in NOTE_FORMATS],
                key=lambda kv: kv[1],
                reverse=True,
            )
            best_note_fmt = ranked_notes[0][0]

            print("\n=== TOP 3 NOTE FORMATS BY MEAN GATE ACCURACY ===")
            for i, (fmt, _) in enumerate(ranked_notes[:3], start=1):
                te = note_results[fmt]["test_eval"]
                print(f"\n#{i} {fmt} @ train_frac={train_frac:.2f}")
                print(f"  task_acc       : {te['task_acc']:.4f}")
                print(f"  gate_acc       : {te['gate_acc']:.4f}")
                print(f"  regret         : {te['regret']:.4f}")
                print(f"  best_single_acc: {best_single_acc:.4f}")
                print(f"  oracle_task_acc: {oracle_task_acc:.4f}")

            print(f"\nBest note format for this dataset (by gate accuracy): {best_note_fmt}")

            # Signal family comparison
            notes_tr = note_results[best_note_fmt]["train_notes"]
            notes_te = note_results[best_note_fmt]["test_notes"]
            note_vec = note_results[best_note_fmt]["vec"]
            X_note_tr = note_vec.transform(notes_tr)
            X_note_te = note_vec.transform(notes_te)

            meta_tr = build_meta_block(gate_preds_tr, top1_tr, margin_tr, entropy_tr)
            meta_te = build_meta_block(gate_preds_te, top1_te, margin_te, entropy_te)
            meta_scaler = StandardScaler()
            meta_tr = meta_scaler.fit_transform(meta_tr).astype(np.float32)
            meta_te = meta_scaler.transform(meta_te).astype(np.float32)
            meta_tr = to_sparse_block(meta_tr)
            meta_te = to_sparse_block(meta_te)

            data_tr, data_te, data_kind = build_data_block(dataset_name, X_gate_train, X_test, seed)
            if data_kind == "dense":
                data_tr = to_sparse_block(data_tr)
                data_te = to_sparse_block(data_te)

            fam_rows = []
            for family in FAMILIES:
                Xtr, Xte = build_family_inputs(family, X_note_tr, X_note_te, meta_tr, meta_te, data_tr, data_te)
                clf = fit_router(Xtr, best_gate_tr, seed)
                te_eval = evaluate_router(clf, Xte, gate_preds_te, gain_te, y_test)
                fam_rows.append({
                    "family": family,
                    "train_frac": train_frac,
                    "seed": seed,
                    "task_acc": te_eval["task_acc"],
                    "gate_acc": te_eval["gate_acc"],
                    "regret": te_eval["regret"],
                    "best_single_acc": best_single_acc,
                    "oracle_task_acc": oracle_task_acc,
                    "pairwise_agreement": pairwise_mean,
                    "router_eval": te_eval,
                    "gate_preds_test": gate_preds_te,
                    "gate_gain_test": gain_te,
                    "y_test": np.asarray(y_test, dtype=np.int64),
                    "note_eval": te_eval,
                })
                all_rows.append({
                    "dataset": dataset_name,
                    "family": family,
                    "note_fmt": best_note_fmt if "note" in family or family == "all_signals" else "-",
                    "train_frac": train_frac,
                    "seed": seed,
                    "task_acc": te_eval["task_acc"],
                    "gate_acc": te_eval["gate_acc"],
                    "regret": te_eval["regret"],
                    "best_single_acc": best_single_acc,
                    "oracle_task_acc": oracle_task_acc,
                    "pairwise_agreement": pairwise_mean,
                    "router_eval": te_eval,
                    "gate_preds_test": gate_preds_te,
                    "gate_gain_test": gain_te,
                    "y_test": np.asarray(y_test, dtype=np.int64),
                    "note_eval": te_eval,
                })

            # summarize families
            family_summary = {}
            for family in FAMILIES:
                rs = [r for r in fam_rows if r["family"] == family]
                family_summary[family] = {
                    "task_acc_mean": mean_std([r["task_acc"] for r in rs])[0],
                    "task_acc_std": mean_std([r["task_acc"] for r in rs])[1],
                    "gate_acc_mean": mean_std([r["gate_acc"] for r in rs])[0],
                    "gate_acc_std": mean_std([r["gate_acc"] for r in rs])[1],
                    "regret_mean": mean_std([r["regret"] for r in rs])[0],
                    "regret_std": mean_std([r["regret"] for r in rs])[1],
                    "best_single_acc_mean": mean_std([r["best_single_acc"] for r in rs])[0],
                    "oracle_task_acc_mean": mean_std([r["oracle_task_acc"] for r in rs])[0],
                    "pairwise_agreement_mean": mean_std([r["pairwise_agreement"] for r in rs])[0],
                }

            ranked_fams = sorted(family_summary.items(), key=lambda kv: kv[1]["task_acc_mean"], reverse=True)
            best_family = ranked_fams[0][0]

            print("\n=== TOP 3 SIGNAL FAMILIES BY MEAN TASK ACCURACY ===")
            for i, (family, st) in enumerate(ranked_fams[:3], start=1):
                print(f"\n#{i} {family} @ train_frac={train_frac:.2f}")
                print(f"  task_acc        : {st['task_acc_mean']:.4f} ± {st['task_acc_std']:.4f}")
                print(f"  gate_acc        : {st['gate_acc_mean']:.4f} ± {st['gate_acc_std']:.4f}")
                print(f"  regret          : {st['regret_mean']:.4f} ± {st['regret_std']:.4f}")
                print(f"  best_single_acc : {st['best_single_acc_mean']:.4f}")
                print(f"  oracle_task_acc  : {st['oracle_task_acc_mean']:.4f}")
                print(f"  pairwise_agree   : {st['pairwise_agreement_mean']:.4f}")

            print(f"\nBest signal family for this dataset: {best_family}")

            # Deep dive on best family
            focus_rows = [r for r in fam_rows if r["family"] == best_family]
            conf_all = []
            entropy_all = []
            margin_all = []
            disagreement_all = []
            miss_all = []
            regret_all = []

            for r in focus_rows:
                te = r["router_eval"]
                gate_preds_test = r["gate_preds_test"]
                pair_agree_per_sample = []
                for a in range(4):
                    for b in range(a + 1, 4):
                        pair_agree_per_sample.append((gate_preds_test[:, a] == gate_preds_test[:, b]).astype(np.float32))
                pair_agree_per_sample = np.stack(pair_agree_per_sample, axis=1).mean(axis=1)
                disagreement = 1.0 - pair_agree_per_sample

                conf_all.append(te["conf"])
                entropy_all.append(te["entropy"])
                margin_all.append(te["margin"])
                disagreement_all.append(disagreement)
                miss_all.append(te["miss"])
                regret_all.append(te["regret"])

            conf_all = np.concatenate(conf_all)
            entropy_all = np.concatenate(entropy_all)
            margin_all = np.concatenate(margin_all)
            disagreement_all = np.concatenate(disagreement_all)
            miss_all = np.concatenate(miss_all)

            hit_rate = 1.0 - miss_all.mean()
            print("\n=== ORACLE-MISS DEEP DIVE FOR BEST FAMILY ===")
            print(f"Best family: {best_family} | canonical note format: {best_note_fmt}")
            print(f"Overall gate hit rate: {hit_rate:.4f}")
            print(f"Overall oracle regret : {float(np.mean(regret_all)):.4f}")

            print("\nWhen the router is right/wrong:")
            print(quartile_report(conf_all, 1.0 - miss_all, "router confidence (hit rate)"))
            print(quartile_report(entropy_all, 1.0 - miss_all, "router entropy (hit rate)"))
            print(quartile_report(margin_all, 1.0 - miss_all, "router margin (hit rate)"))
            print(quartile_report(disagreement_all, 1.0 - miss_all, "expert disagreement (hit rate)"))

            print("\nWhen the router misses the oracle:")
            print(quartile_report(conf_all, miss_all, "router confidence (miss rate)"))
            print(quartile_report(entropy_all, miss_all, "router entropy (miss rate)"))
            print(quartile_report(margin_all, miss_all, "router margin (miss rate)"))
            print(quartile_report(disagreement_all, miss_all, "expert disagreement (miss rate)"))

            if len(miss_all) > 1:
                c_conf = float(np.corrcoef(miss_all, 1.0 - conf_all)[0, 1])
                c_ent = float(np.corrcoef(miss_all, entropy_all)[0, 1])
                c_margin = float(np.corrcoef(miss_all, 1.0 - margin_all)[0, 1])
                c_dis = float(np.corrcoef(miss_all, disagreement_all)[0, 1])
            else:
                c_conf = c_ent = c_margin = c_dis = 0.0

            print("\nCorrelations with misses:")
            print(f"  miss vs low confidence : {c_conf:+.4f}")
            print(f"  miss vs high entropy    : {c_ent:+.4f}")
            print(f"  miss vs low margin      : {c_margin:+.4f}")
            print(f"  miss vs disagreement    : {c_dis:+.4f}")

            best_note_overall = ranked_notes[0][0]
            best_fam_overall = ranked_fams[0][0]

            print("\n=== DATASET READ ===")
            print(f"Best note format overall : {best_note_overall} @ train_frac={train_frac:.2f}")
            print(f"Best family overall      : {best_fam_overall} @ train_frac={train_frac:.2f}")
            print("Use the family comparison to see whether note text, note format, or raw data features matter most.")
            print("Use the oracle-miss deep dive to see when the router is right, when it misses, and whether uncertainty/disagreement explains those misses.")

    return all_rows

# -----------------------------
# Run all datasets
# -----------------------------
for ds_name, cfg in DATASETS.items():
    if ds_name == "Breast Cancer":
        run_dataset(
            dataset_name=ds_name,
            loader_fn=load_breast_cancer_benchmark,
            build_experts_fn=build_tabular_experts,
            predict_experts_fn=predict_tabular_experts,
            train_fracs=cfg["train_fracs"],
            test_n=cfg["test_n"],
            seeds=SEEDS,
        )
    elif ds_name == "FashionMNIST":
        run_dataset(
            dataset_name=ds_name,
            loader_fn=load_fashion_mnist_benchmark,
            build_experts_fn=build_image_experts,
            predict_experts_fn=predict_image_experts,
            train_fracs=cfg["train_fracs"],
            test_n=cfg["test_n"],
            seeds=SEEDS,
        )
    else:
        run_dataset(
            dataset_name=ds_name,
            loader_fn=load_20newsgroups_benchmark,
            build_experts_fn=build_text_experts,
            predict_experts_fn=predict_text_experts,
            train_fracs=cfg["train_fracs"],
            test_n=cfg["test_n"],
            seeds=SEEDS,
        )

print("\nDone.")

