#   1) Re-runs the compact final stress test
#   2) Picks best note format per run
#   3) Picks best signal family per dataset
#   4) Prints a paper-ready summary
#   5) Computes calibration (ECE) + selective routing
#
# Assumes these already exist in your notebook:
#   - DATASETS, SEEDS, NOTE_FORMATS, FAMILIES, GATE_NAMES, GATE_COST
#   - load_breast_cancer_benchmark, load_fashion_mnist_benchmark, load_20newsgroups_benchmark
#   - build_tabular_experts, build_image_experts, build_text_experts
