import json
import random
import warnings
from collections import Counter, defaultdict

import numpy as np
from scipy.sparse import csr_matrix, hstack as sparse_hstack, issparse
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.decomposition import PCA
from sklearn.pipeline import Pipeline
from sklearn.linear_model import LogisticRegression, SGDClassifier
from sklearn.naive_bayes import GaussianNB, ComplementNB
from sklearn.neighbors import KNeighborsClassifier
from sklearn.tree import DecisionTreeClassifier
from sklearn.dummy import DummyClassifier
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics import accuracy_score
from sklearn.datasets import load_breast_cancer, fetch_20newsgroups

warnings.filterwarnings("ignore")

BASE_SEED = 42

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)

def fmt3(x):
    return f"{float(x):.3f}"

def mean_std(vals):
    arr = np.asarray(vals, dtype=np.float32)
    return float(arr.mean()), float(arr.std(ddof=0))

def stratified_subsample(X, y, n_samples, seed):
    n = X.shape[0] if hasattr(X, "shape") else len(y)
    if n_samples >= n:
        return X, y
    X_sub, _, y_sub, _ = train_test_split(
        X, y, train_size=n_samples, stratify=y, random_state=seed
    )
    return X_sub, y_sub

def get_classes(model):
    if hasattr(model, "classes_"):
        return np.asarray(model.classes_)
    if hasattr(model, "named_steps"):
        for step in reversed(list(model.named_steps.values())):
            if hasattr(step, "classes_"):
                return np.asarray(step.classes_)
    return np.array([0], dtype=np.int64)

def full_proba(model, X, n_classes=4):
    proba = model.predict_proba(X)
    if proba.ndim == 1:
        proba = proba.reshape(-1, 1)
    classes = get_classes(model)
    out = np.zeros((X.shape[0], n_classes), dtype=np.float32)
    for j, c in enumerate(classes):
        out[:, int(c)] = proba[:, j]
    return out

def fit_router(X_train, y_train, seed):
    y_train = np.asarray(y_train, dtype=np.int64)
    uniq = np.unique(y_train)
    if len(uniq) < 2:
        clf = DummyClassifier(strategy="constant", constant=int(uniq[0]))
        clf.fit(X_train, y_train)
        return clf
    clf = SGDClassifier(
        loss="log_loss",
        alpha=1e-4,
        max_iter=4000,
        tol=1e-4,
        random_state=seed,
        class_weight="balanced",
    )
    clf.fit(X_train, y_train)
    return clf

def evaluate_router(clf, X_eval, gate_preds, gate_gain, y_true):
    pred_gate = np.asarray(clf.predict(X_eval), dtype=np.int64)
    proba = full_proba(clf, X_eval, n_classes=4)
    conf = np.max(proba, axis=1)
    p_sorted = np.sort(proba, axis=1)
    margin = p_sorted[:, -1] - p_sorted[:, -2] if p_sorted.shape[1] > 1 else np.zeros(X_eval.shape[0], dtype=np.float32)
    entropy = (-np.sum(proba * np.log(proba + 1e-12), axis=1)) / np.log(proba.shape[1])

    best_gate = np.argmax(gate_gain, axis=1)
    chosen_task_pred = np.array([gate_preds[i, pred_gate[i]] for i in range(X_eval.shape[0])], dtype=np.int64)
    task_acc = accuracy_score(y_true, chosen_task_pred)
    gate_acc = float(np.mean(pred_gate == best_gate))
    regret = float(np.mean(np.max(gate_gain, axis=1) - gate_gain[np.arange(X_eval.shape[0]), pred_gate]))

    return {
        "pred_gate": pred_gate,
        "proba": proba,
        "conf": conf,
        "margin": margin,
        "entropy": entropy,
        "best_gate": best_gate,
        "task_acc": task_acc,
        "gate_acc": gate_acc,
        "regret": regret,
        "chosen_task_pred": chosen_task_pred,
        "correct": (chosen_task_pred == y_true).astype(np.float32),
        "miss": (pred_gate != best_gate).astype(np.float32),
    }

def build_data_block(dataset_name, X_train_raw, X_test_raw, seed):
    if dataset_name == "Breast Cancer":
        scaler = StandardScaler()
        Xtr = scaler.fit_transform(np.asarray(X_train_raw, dtype=np.float32)).astype(np.float32)
        Xte = scaler.transform(np.asarray(X_test_raw, dtype=np.float32)).astype(np.float32)
        return Xtr, Xte, "dense"

    if dataset_name == "FashionMNIST":
        pipe = Pipeline([
            ("scaler", StandardScaler()),
            ("pca", PCA(n_components=50, random_state=seed)),
        ])
        Xtr = pipe.fit_transform(np.asarray(X_train_raw, dtype=np.float32)).astype(np.float32)
        Xte = pipe.transform(np.asarray(X_test_raw, dtype=np.float32)).astype(np.float32)
        return Xtr, Xte, "dense"

    vec = TfidfVectorizer(max_features=12000, ngram_range=(1, 2), min_df=2)
    Xtr = vec.fit_transform(np.asarray(X_train_raw, dtype=object))
    Xte = vec.transform(np.asarray(X_test_raw, dtype=object))
    return Xtr, Xte, "sparse"

def to_sparse_block(X):
    if issparse(X):
        return X.tocsr()
    return csr_matrix(np.asarray(X, dtype=np.float32))

def build_meta_block(gate_preds, top1_prob, margin, entropy):
    pair_agree_vals = []
    for a in range(4):
        for b in range(a + 1, 4):
            pair_agree_vals.append((gate_preds[:, a] == gate_preds[:, b]).astype(np.float32))
    pair_agree_vals = np.stack(pair_agree_vals, axis=1)
    pair_agree_mean = pair_agree_vals.mean(axis=1, keepdims=True)
    pair_agree_std = pair_agree_vals.std(axis=1, keepdims=True)
    disagreement = 1.0 - pair_agree_mean

    mem_top1 = top1_prob[:, 2:3]
    mem_margin = margin[:, 2:3]
    mem_entropy = entropy[:, 2:3]
    other_top1_mean = np.delete(top1_prob, 2, axis=1).mean(axis=1, keepdims=True)
    mem_advantage = mem_top1 - other_top1_mean

    top1_mean = top1_prob.mean(axis=1, keepdims=True)
    top1_std = top1_prob.std(axis=1, keepdims=True)
    margin_mean = margin.mean(axis=1, keepdims=True)
    margin_std = margin.std(axis=1, keepdims=True)
    entropy_mean = entropy.mean(axis=1, keepdims=True)
    entropy_std = entropy.std(axis=1, keepdims=True)

    meta = np.concatenate([
        top1_mean, top1_std,
        margin_mean, margin_std,
        entropy_mean, entropy_std,
        pair_agree_mean, pair_agree_std, disagreement,
        mem_top1, mem_margin, mem_entropy, mem_advantage,
    ], axis=1).astype(np.float32)
    return meta

def sample_pair_agreement(gate_preds_i):
    cnt = 0
    agree = 0
    for a in range(4):
        for b in range(a + 1, 4):
            agree += int(gate_preds_i[a] == gate_preds_i[b])
            cnt += 1
    return agree / max(cnt, 1)

def sample_content(dataset_name, modality, i, gate_preds, top1_prob, margin, entropy):
    pair_agree = sample_pair_agreement(gate_preds[i])
    cand = []
    for g in range(4):
        cand.append({
            "gate": GATE_NAMES[g],
            "pred": int(gate_preds[i, g]),
            "top1": float(top1_prob[i, g]),
            "margin": float(margin[i, g]),
            "entropy": float(entropy[i, g]),
            "proxy": float(top1_prob[i, g] - GATE_COST[g]),
        })
    cand = sorted(cand, key=lambda d: d["proxy"], reverse=True)
    return {
        "dataset": dataset_name,
        "modality": modality,
        "signals": {
            "pair_agree": float(pair_agree),
            "top1_mean": float(np.mean(top1_prob[i])),
            "margin_mean": float(np.mean(margin[i])),
            "entropy_mean": float(np.mean(entropy[i])),
        },
        "candidates": cand,
        "best_hint": cand[0]["gate"],
    }

def render_note(content, fmt):
    if fmt == "json":
        return json.dumps(content, sort_keys=True, separators=(",", ":"))
    if fmt == "table":
        lines = []
        lines.append(f"DATASET | {content['dataset']}")
        lines.append(f"MODALITY | {content['modality']}")
        lines.append("")
        lines.append("| Signal | Value |")
        lines.append("|---|---:|")
        for k, v in content["signals"].items():
            lines.append(f"| {k} | {fmt3(v)} |")
        lines.append("")
        lines.append("| Gate | Pred | Top1 | Margin | Entropy | Proxy |")
        lines.append("|---|---:|---:|---:|---:|---:|")
        for c in content["candidates"]:
            lines.append(f"| {c['gate']} | {c['pred']} | {fmt3(c['top1'])} | {fmt3(c['margin'])} | {fmt3(c['entropy'])} | {fmt3(c['proxy'])} |")
        lines.append(f"Best hint | {content['best_hint']}")
        return "\n".join(lines)
    if fmt == "qa":
        lines = []
        lines.append(f"Q1: What kind of data is this?\nA1: {content['modality']} in {content['dataset']}.")
        s = content["signals"]
        lines.append(
            "Q2: What are the main signals?\nA2: "
            f"pair_agree={fmt3(s['pair_agree'])}, top1_mean={fmt3(s['top1_mean'])}, "
            f"margin_mean={fmt3(s['margin_mean'])}, entropy_mean={fmt3(s['entropy_mean'])}."
        )
        cand = "; ".join([f"{c['gate']} proxy={fmt3(c['proxy'])}" for c in content["candidates"]])
        lines.append("Q3: Which gates look strongest?\nA3: " + cand + ".")
        lines.append(f"Q4: Best hint?\nA4: {content['best_hint']}.")
        return "\n".join(lines)

    s = content["signals"]
    cand = " | ".join([f"{c['gate']}({fmt3(c['proxy'])})" for c in content["candidates"]])
    return (
        f"dataset={content['dataset']};modality={content['modality']};"
        f"pair_agree={fmt3(s['pair_agree'])};top1={fmt3(s['top1_mean'])};margin={fmt3(s['margin_mean'])};entropy={fmt3(s['entropy_mean'])};"
        f"cands={cand};best_hint={content['best_hint']}"
    )

def build_note_texts(dataset_name, modality, gate_preds, top1_prob, margin, entropy, fmt):
    texts = []
    for i in range(gate_preds.shape[0]):
        content = sample_content(dataset_name, modality, i, gate_preds, top1_prob, margin, entropy)
        texts.append(render_note(content, fmt))
    return texts

def compute_gate_labels(gate_probs, y_true):
    true_prob = np.stack([gate_probs[g][np.arange(len(y_true)), y_true] for g in range(4)], axis=1)
    gain = true_prob - GATE_COST[None, :]
    best_gate = np.argmax(gain, axis=1)
    return true_prob, gain, best_gate

def evaluate_experts(gate_preds, y_true, best_gate):
    single_accs = [accuracy_score(y_true, gate_preds[:, g]) for g in range(4)]
    best_single_idx = int(np.argmax(single_accs))
    best_single_acc = float(single_accs[best_single_idx])
    oracle_task_acc = float(np.mean([gate_preds[i, best_gate[i]] == y_true[i] for i in range(len(y_true))]))
    pairwise_mean = float(np.mean([np.mean(gate_preds[:, a] == gate_preds[:, b]) for a in range(4) for b in range(a + 1, 4)]))
    return best_single_idx, best_single_acc, oracle_task_acc, pairwise_mean

def build_family_inputs(family, note_train, note_test, meta_train, meta_test, data_train, data_test):
    if family == "note_only":
        return note_train, note_test
    if family == "meta_only":
        return meta_train, meta_test
    if family == "data_only":
        return data_train, data_test
    if family == "note_plus_meta":
        return sparse_hstack([note_train, meta_train]), sparse_hstack([note_test, meta_test])
    if family == "note_plus_data":
        return sparse_hstack([note_train, data_train]), sparse_hstack([note_test, data_test])
    if family == "meta_plus_data":
        return sparse_hstack([meta_train, data_train]), sparse_hstack([meta_test, data_test])
    if family == "all_signals":
        return sparse_hstack([note_train, meta_train, data_train]), sparse_hstack([note_test, meta_test, data_test])
    raise ValueError(f"Unknown family: {family}")

def ece_score(conf, correct, n_bins=10):
    conf = np.asarray(conf, dtype=np.float32)
    correct = np.asarray(correct, dtype=np.float32)
    if len(conf) == 0:
        return 0.0
    bins = np.linspace(0.0, 1.0, n_bins + 1)
    ece = 0.0
    rows = []
    for i in range(n_bins):
        lo, hi = bins[i], bins[i + 1]
        if i == n_bins - 1:
            mask = (conf >= lo) & (conf <= hi)
        else:
            mask = (conf >= lo) & (conf < hi)
        n = int(mask.sum())
        if n == 0:
            continue
        avg_conf = float(conf[mask].mean())
        emp_acc = float(correct[mask].mean())
        gap = emp_acc - avg_conf
        ece += (n / len(conf)) * abs(gap)
        rows.append((f"{lo:.1f}-{hi:.1f}", n, avg_conf, emp_acc, gap))
    return float(ece), rows

def sweep_selective_routing(rows, thresholds=None):
    if thresholds is None:
        thresholds = np.round(np.linspace(0.0, 0.95, 10), 2).tolist()

    conf_all = np.concatenate([r["router_eval"]["conf"] for r in rows])
    correct_all = np.concatenate([r["router_eval"]["correct"] for r in rows])
    pred_gate_all = np.concatenate([r["router_eval"]["pred_gate"] for r in rows])
    best_gate_all = np.concatenate([r["router_eval"]["best_gate"] for r in rows])
    chosen_pred_all = np.concatenate([r["router_eval"]["chosen_task_pred"] for r in rows])
    y_all = np.concatenate([r["y_test"] for r in rows])
    gate_gain_all = np.concatenate([r["gate_gain_test"] for r in rows], axis=0)

    out = []
    for thr in thresholds:
        keep = conf_all >= thr
        cov = float(keep.mean())
        if keep.sum() == 0:
            out.append((thr, cov, np.nan, np.nan, np.nan))
            continue
        task_acc = float((chosen_pred_all[keep] == y_all[keep]).mean())
        gate_acc = float((pred_gate_all[keep] == best_gate_all[keep]).mean())
        regret = float((np.max(gate_gain_all[keep], axis=1) - gate_gain_all[keep, pred_gate_all[keep]]).mean())
        out.append((thr, cov, task_acc, gate_acc, regret))
    return out

def choose_best_note_format(note_rows):
    summary = {}
    for fmt in NOTE_FORMATS:
        rs = [r for r in note_rows if r["note_fmt"] == fmt]
        if not rs:
            continue
        summary[fmt] = mean_std([r["gate_acc"] for r in rs])[0]
    return max(summary.items(), key=lambda kv: kv[1])[0] if summary else NOTE_FORMATS[0]

def choose_best_family(fam_rows):
    summary = {}
    for fam in FAMILIES:
        rs = [r for r in fam_rows if r["family"] == fam]
        if not rs:
            continue
        summary[fam] = mean_std([r["task_acc"] for r in rs])[0]
    return max(summary.items(), key=lambda kv: kv[1])[0] if summary else FAMILIES[0]

def run_dataset_closure(dataset_name, loader_fn, build_experts_fn, predict_experts_fn, train_fracs, test_n, seeds):
    X_train_full, y_train_full, X_test_full, y_test_full = loader_fn(BASE_SEED)
    if test_n is not None:
        X_test, y_test = stratified_subsample(X_test_full, y_test_full, test_n, BASE_SEED)
    else:
        X_test, y_test = X_test_full, y_test_full

    modality = "tabular" if dataset_name == "Breast Cancer" else ("image" if dataset_name == "FashionMNIST" else "text")

    rows = []
    for train_frac in train_fracs:
        train_n = max(int((X_train_full.shape[0] if hasattr(X_train_full, "shape") else len(X_train_full)) * train_frac), 2)

        for seed in seeds:
            set_seed(seed)
            X_sub, y_sub = stratified_subsample(X_train_full, y_train_full, train_n, seed)
            X_expert_train, X_gate_train, y_expert_train, y_gate_train = train_test_split(
                X_sub, y_sub, test_size=0.20, random_state=seed, stratify=y_sub
            )

            experts = build_experts_fn(seed)
            for m in experts:
                m.fit(X_expert_train, y_expert_train)

            gate_preds_tr, gate_probs_tr, top1_tr, margin_tr, entropy_tr = predict_experts_fn(experts, X_gate_train)
            gate_preds_te, gate_probs_te, top1_te, margin_te, entropy_te = predict_experts_fn(experts, X_test)

            _, gain_tr, best_gate_tr = compute_gate_labels(gate_probs_tr, y_gate_train)
            _, gain_te, best_gate_te = compute_gate_labels(gate_probs_te, y_test)
            best_single_idx, best_single_acc, oracle_task_acc, pairwise_mean = evaluate_experts(gate_preds_te, y_test, best_gate_te)

            note_results = {}
            for fmt in NOTE_FORMATS:
                notes_tr = build_note_texts(dataset_name, modality, gate_preds_tr, top1_tr, margin_tr, entropy_tr, fmt)
                notes_te = build_note_texts(dataset_name, modality, gate_preds_te, top1_te, margin_te, entropy_te, fmt)

                note_vec = TfidfVectorizer(analyzer="char", ngram_range=(3, 5), min_df=2, max_features=60000)
                X_note_tr = note_vec.fit_transform(notes_tr)
                X_note_te = note_vec.transform(notes_te)

                clf = fit_router(X_note_tr, best_gate_tr, seed)
                tr_eval = evaluate_router(clf, X_note_tr, gate_preds_tr, gain_tr, y_gate_train)
                te_eval = evaluate_router(clf, X_note_te, gate_preds_te, gain_te, y_test)

                note_results[fmt] = {
                    "train_eval": tr_eval,
                    "test_eval": te_eval,
                    "train_notes": notes_tr,
                    "test_notes": notes_te,
                    "vec": note_vec,
                }

            best_note_fmt = choose_best_note_format([
                {
                    "note_fmt": fmt,
                    "gate_acc": note_results[fmt]["test_eval"]["gate_acc"],
                } for fmt in NOTE_FORMATS
            ])
            note_only_best = note_results[best_note_fmt]

            note_tr = note_only_best["train_notes"]
            note_te = note_only_best["test_notes"]
            note_vec = note_only_best["vec"]
            X_note_tr = note_vec.transform(note_tr)
            X_note_te = note_vec.transform(note_te)

            meta_tr = build_meta_block(gate_preds_tr, top1_tr, margin_tr, entropy_tr)
            meta_te = build_meta_block(gate_preds_te, top1_te, margin_te, entropy_te)
            meta_scaler = StandardScaler()
            meta_tr = meta_scaler.fit_transform(meta_tr).astype(np.float32)
            meta_te = meta_scaler.transform(meta_te).astype(np.float32)
            meta_tr = to_sparse_block(meta_tr)
            meta_te = to_sparse_block(meta_te)

            data_tr, data_te, data_kind = build_data_block(dataset_name, X_gate_train, X_test, seed)
            if data_kind == "dense":
                data_tr = to_sparse_block(data_tr)
                data_te = to_sparse_block(data_te)

            fam_rows = []
            for fam in FAMILIES:
                Xtr, Xte = build_family_inputs(fam, X_note_tr, X_note_te, meta_tr, meta_te, data_tr, data_te)
                clf = fit_router(Xtr, best_gate_tr, seed)
                te_eval = evaluate_router(clf, Xte, gate_preds_te, gain_te, y_test)

                row = {
                    "dataset": dataset_name,
                    "train_frac": train_frac,
                    "train_n": train_n,
                    "seed": seed,
                    "family": fam,
                    "note_fmt": best_note_fmt if "note" in fam or fam == "all_signals" else "-",
                    "task_acc": te_eval["task_acc"],
                    "gate_acc": te_eval["gate_acc"],
                    "regret": te_eval["regret"],
                    "best_single_acc": best_single_acc,
                    "oracle_task_acc": oracle_task_acc,
                    "pairwise_agreement": pairwise_mean,
                    "router_eval": te_eval,
                    "gate_preds_test": gate_preds_te,
                    "gate_gain_test": gain_te,
                    "y_test": np.asarray(y_test, dtype=np.int64),
                }
                fam_rows.append(row)
                rows.append(row)

            # Best note format row bookkeeping
            for fmt in NOTE_FORMATS:
                rows.append({
                    "dataset": dataset_name,
                    "train_frac": train_frac,
                    "train_n": train_n,
                    "seed": seed,
                    "family": "note_only",
                    "note_fmt": fmt,
                    "task_acc": note_results[fmt]["test_eval"]["task_acc"],
                    "gate_acc": note_results[fmt]["test_eval"]["gate_acc"],
                    "regret": note_results[fmt]["test_eval"]["regret"],
                    "best_single_acc": best_single_acc,
                    "oracle_task_acc": oracle_task_acc,
                    "pairwise_agreement": pairwise_mean,
                    "router_eval": note_results[fmt]["test_eval"],
                    "gate_preds_test": gate_preds_te,
                    "gate_gain_test": gain_te,
                    "y_test": np.asarray(y_test, dtype=np.int64),
                })

            best_family = choose_best_family(fam_rows)
            focus_rows = [r for r in fam_rows if r["family"] == best_family]

            # Print compact dataset summary
            note_summary = {}
            for fmt in NOTE_FORMATS:
                rs = [r for r in rows if r["dataset"] == dataset_name and r["train_frac"] == train_frac and r["seed"] == seed and r["note_fmt"] == fmt and r["family"] == "note_only"]
                if rs:
                    note_summary[fmt] = mean_std([r["gate_acc"] for r in rs])[0]
            ranked_notes = sorted(note_summary.items(), key=lambda kv: kv[1], reverse=True)
            best_note = ranked_notes[0][0] if ranked_notes else best_note_fmt

            fam_summary = {fam: mean_std([r["task_acc"] for r in fam_rows if r["family"] == fam])[0] for fam in FAMILIES}
            best_fam = max(fam_summary.items(), key=lambda kv: kv[1])[0]

            print(f"\n==================== {dataset_name} ====================")
            print(f"train_frac={train_frac:.2f} | seed={seed}")
            print(f"Best note format: {best_note}")
            print(f"Best family     : {best_fam}")
            print(f"  task_acc       : {mean_std([r['task_acc'] for r in fam_rows])[0]:.4f}")
            print(f"  gate_acc       : {mean_std([r['gate_acc'] for r in fam_rows])[0]:.4f}")
            print(f"  regret         : {mean_std([r['regret'] for r in fam_rows])[0]:.4f}")
            print(f"  best_single_acc : {best_single_acc:.4f}")
            print(f"  oracle_task_acc  : {oracle_task_acc:.4f}")

    # Dataset-level summaries
    print("\n=== BEST CONFIG COUNTS ACROSS RUNS ===")
    note_counter = Counter([r["note_fmt"] for r in rows if r["family"] == "note_only"])
    fam_counter = Counter([r["family"] for r in rows if r["family"] in FAMILIES])

    print("Top note formats:")
    for k, v in note_counter.most_common(3):
        print(f"  {k:12s} {v}")
    print("Top signal families:")
    for k, v in fam_counter.most_common(3):
        print(f"  {k:12s} {v}")

    print("\n=== RUN-LEVEL MEAN PERFORMANCE ===")
    print(f"  task_acc        : {mean_std([r['task_acc'] for r in rows if r['family'] in FAMILIES])[0]:.4f} ± {mean_std([r['task_acc'] for r in rows if r['family'] in FAMILIES])[1]:.4f}")
    print(f"  gate_acc        : {mean_std([r['gate_acc'] for r in rows if r['family'] in FAMILIES])[0]:.4f} ± {mean_std([r['gate_acc'] for r in rows if r['family'] in FAMILIES])[1]:.4f}")
    print(f"  regret          : {mean_std([r['regret'] for r in rows if r['family'] in FAMILIES])[0]:.4f} ± {mean_std([r['regret'] for r in rows if r['family'] in FAMILIES])[1]:.4f}")
    print(f"  best_single_acc  : {mean_std([r['best_single_acc'] for r in rows if r['family'] in FAMILIES])[0]:.4f} ± {mean_std([r['best_single_acc'] for r in rows if r['family'] in FAMILIES])[1]:.4f}")
    print(f"  oracle_task_acc  : {mean_std([r['oracle_task_acc'] for r in rows if r['family'] in FAMILIES])[0]:.4f} ± {mean_std([r['oracle_task_acc'] for r in rows if r['family'] in FAMILIES])[1]:.4f}")
    print(f"  pairwise_agree   : {mean_std([r['pairwise_agreement'] for r in rows if r['family'] in FAMILIES])[0]:.4f} ± {mean_std([r['pairwise_agreement'] for r in rows if r['family'] in FAMILIES])[1]:.4f}")

    best_family = choose_best_family([r for r in rows if r["family"] in FAMILIES])
    best_family_rows = [r for r in rows if r["family"] == best_family]

    conf_all = np.concatenate([r["router_eval"]["conf"] for r in best_family_rows])
    correct_all = np.concatenate([r["router_eval"]["correct"] for r in best_family_rows])
    miss_all = np.concatenate([r["router_eval"]["miss"] for r in best_family_rows])
    entropy_all = np.concatenate([r["router_eval"]["entropy"] for r in best_family_rows])
    margin_all = np.concatenate([r["router_eval"]["margin"] for r in best_family_rows])
    pred_gate_all = np.concatenate([r["router_eval"]["pred_gate"] for r in best_family_rows])
    best_gate_all = np.concatenate([r["router_eval"]["best_gate"] for r in best_family_rows])
    chosen_pred_all = np.concatenate([r["router_eval"]["chosen_task_pred"] for r in best_family_rows])
    y_all = np.concatenate([r["y_test"] for r in best_family_rows])
    gate_gain_all = np.concatenate([r["gate_gain_test"] for r in best_family_rows], axis=0)

    ece, calib_rows = ece_score(conf_all, correct_all, n_bins=10)

    print("\n=== CALIBRATION SUMMARY ===")
    print(f"  ECE              : {ece:.4f}")
    print(f"  mean_confidence  : {float(conf_all.mean()):.4f}")
    print(f"  mean_accuracy    : {float(correct_all.mean()):.4f}")
    print("\n  bin_range   n     avg_conf  emp_acc   gap")
    for rng, n, avg_conf, emp_acc, gap in calib_rows:
        print(f"  {rng:8s} {n:4d}   {avg_conf:.4f}   {emp_acc:.4f}  {gap:+.4f}")

    select_rows = sweep_selective_routing(best_family_rows, thresholds=np.round(np.linspace(0.0, 0.95, 10), 2).tolist())
    print("\n=== SELECTIVE ROUTING SUMMARY ===")
    print("  thr   coverage  task_acc  gate_acc  regret")
    for thr, cov, ta, ga, rg in select_rows:
        if np.isnan(ta):
            print(f"  {thr:0.2f}   {cov:0.3f}     nan      nan      nan")
        else:
            print(f"  {thr:0.2f}   {cov:0.3f}     {ta:0.4f}    {ga:0.4f}   {rg:0.4f}")

    best_thr, best_cov, best_ta, _, _ = max(
        [(t, c, a, g, r) for t, c, a, g, r in select_rows if not np.isnan(a)],
        key=lambda x: x[2]
    )
    full_cov_ta = float((chosen_pred_all == y_all).mean())

    print("\n=== SELECTIVE ROUTING TAKEAWAY ===")
    print(f"  best_threshold_by_task_acc : {best_thr:.2f}")
    print(f"  best_threshold_coverage    : {best_cov:.3f}")
    print(f"  best_threshold_task_acc    : {best_ta:.4f}")
    print(f"  full_coverage_task_acc     : {full_cov_ta:.4f}")

    calibration_reason = "router confidence is moderately calibrated" if ece < 0.15 else "router confidence is weakly calibrated"
    routing_reason = "selective routing gives a small gain" if best_ta - full_cov_ta < 0.05 else "selective routing gives a real accuracy gain"

    print("\n=== FINAL READ ===")
    print(f"  best_family           : {best_family}")
    print(f"  calibration_reason    : {calibration_reason}")
    print(f"  routing_reason        : {routing_reason}")

    return rows

# -----------------------------
# Run all datasets
# -----------------------------
ALL_ROWS = []
for ds_name, cfg in DATASETS.items():
    if ds_name == "Breast Cancer":
        ALL_ROWS.extend(
            run_dataset_closure(
                dataset_name=ds_name,
                loader_fn=load_breast_cancer_benchmark,
                build_experts_fn=build_tabular_experts,
                predict_experts_fn=predict_tabular_experts,
                train_fracs=cfg["train_fracs"],
                test_n=cfg["test_n"],
                seeds=SEEDS,
            )
        )
    elif ds_name == "FashionMNIST":
        ALL_ROWS.extend(
            run_dataset_closure(
                dataset_name=ds_name,
                loader_fn=load_fashion_mnist_benchmark,
                build_experts_fn=build_image_experts,
                predict_experts_fn=predict_image_experts,
                train_fracs=cfg["train_fracs"],
                test_n=cfg["test_n"],
                seeds=SEEDS,
            )
        )
    else:
        ALL_ROWS.extend(
            run_dataset_closure(
                dataset_name=ds_name,
                loader_fn=load_20newsgroups_benchmark,
                build_experts_fn=build_text_experts,
                predict_experts_fn=predict_text_experts,
                train_fracs=cfg["train_fracs"],
                test_n=cfg["test_n"],
                seeds=SEEDS,
            )
        )

print("\nDone.")
